> [9b0aec1](https://github.com/bitcoin/bitcoin/pull/36033/changes/9b0aec18bd87a3a95ade4620668ace56f57498c3) _compat: Use std::byteswap_:

The three `internal_bswap` functions now only forward to `std::byteswap`.

<details><summary>Example patch</summary>

```patch
diff --git a/src/common/bip352.h b/src/common/bip352.h
index fd9e0e711d..b29b6be11e 100644
--- a/src/common/bip352.h
+++ b/src/common/bip352.h
@@ -7,7 +7,6 @@

 #include <addresstype.h>
 #include <attributes.h>
-#include <compat/byteswap.h>
 #include <key.h>
 #include <primitives/transaction.h>
 #include <pubkey.h>
@@ -15,6 +14,7 @@
 #include <util/expected.h>

 #include <array>
+#include <bit>
 #include <compare>
 #include <cstdint>
 #include <cstring>
@@ -62,7 +62,7 @@ struct BIP352Comparator {
         // sort of the outpoints, using the 36-byte serialization:
         // <txid, 32-bytes little-endian>:<vout, 4-bytes little-endian>
         if (a.hash != b.hash) return a.hash < b.hash;
-        return internal_bswap_32(a.n) < internal_bswap_32(b.n);
+        return std::byteswap(a.n) < std::byteswap(b.n);
     }
 };

